/**
 * GitHub Pages / iOS Safari preview compatibility: embed the six unchanged PNG
 * layers directly to avoid binary subresource interstitials and cross-origin
 * decoding issues in temporary raw-file proxies. No runtime network access.
 * Source assets are preserved in assets/titan/ for comparison and regeneration.
 */
export const TITAN_IMAGES = Object.freeze({
  "leg-l": "data:image/png;base64,",
  "leg-r": "data:image/png;base64,",
  "torso": "data:image/png;base64,",
  "arm-l": "data:image/png;base64,",
  "arm-r": "data:image/png;base64,",
  "head": "data:image/png;base64,"
});
